CREATE OR REPLACE FUNCTION rakeezx.complete_account_profile(p_teacher_name text, p_phone text, p_teacher_form text, p_school_name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_owner uuid := auth.uid();
begin
  if v_owner is null then raise exception using errcode='42501', message='Authentication required'; end if;
  if pg_catalog.btrim(coalesce(p_phone,'')) !~ '^05[0-9]{8}$' then
    raise exception using errcode='22023', message='Invalid Saudi mobile';
  end if;
  perform rakeezx.complete_account_profile_before_provisioning_0297(
    p_teacher_name,p_phone,p_teacher_form,p_school_name);
  perform pg_catalog.set_config('rakeezx.account_provisioning_control','allow',true);
  update rakeezx.profile set provisioning_state='PROVISIONING_REQUIRED'
    where owner_id=v_owner and provisioning_state='PROFILE_REQUIRED';
  return rakeezx.account_contract();
end;
$function$

CREATE OR REPLACE FUNCTION rakeezx.n58_guard_calendar_contract()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_row jsonb; v_old jsonb; v_year rakeezx.years%rowtype;
  v_calendar rakeezx.calendars%rowtype; v_term rakeezx.terms%rowtype;
  v_year_id text; v_context jsonb; v_fresh_restore boolean;
begin
  if tg_op='INSERT' and auth.uid() is not null then new.owner_id:=auth.uid(); end if;
  v_row:=case when tg_op='DELETE' then pg_catalog.to_jsonb(old) else pg_catalog.to_jsonb(new) end;
  if tg_op='UPDATE' then
    v_old:=pg_catalog.to_jsonb(old);
    if (new.owner_id,new.id) is distinct from (old.owner_id,old.id) then
      raise exception using errcode='22023',message='N58_IMMUTABLE_RECORD_IDENTITY'; end if;
    -- Preserve the existing tombstone trigger's silent, immutable update result.
    if old.deleted_at is not null then return null; end if;
  end if;

  case tg_table_name
    when 'years' then v_year_id:=v_row->>'id';
    when 'terms','calendars','sections' then v_year_id:=v_row->>'year_id';
    when 'calendar_days' then
      select * into v_calendar from rakeezx.calendars where owner_id=(v_row->>'owner_id')::uuid
        and id=v_row->>'calendar_id';
      v_year_id:=v_calendar.year_id;
    when 'teachings' then
      select * into v_term from rakeezx.terms where owner_id=(v_row->>'owner_id')::uuid and id=v_row->>'term_id';
      v_year_id:=v_term.year_id;
    when 'sessions' then
      select t.* into v_term from rakeezx.terms t join rakeezx.teachings x
        on x.owner_id=t.owner_id and x.term_id=t.id
        where x.owner_id=(v_row->>'owner_id')::uuid and x.id=v_row->>'teaching_id';
      v_year_id:=v_term.year_id;
  end case;
  select * into v_year from rakeezx.years where owner_id=(v_row->>'owner_id')::uuid and id=v_year_id;
  v_fresh_restore:=rakeezx.n58_restore_creating_year((v_row->>'owner_id')::uuid,v_year_id);

  if tg_table_name='years' then
    if tg_op='DELETE' then
      if old.calendar_preset_id is not null then
        raise exception using errcode='22023',message='N58_SELECTED_YEAR_RETIREMENT_BLOCKED'; end if;
    else
      if new.calendar_preset_id is not null and not rakeezx.n58_valid_preset(new.calendar_preset_id,new.hijri_start,new.hijri_end) then
        raise exception using errcode='22023',message='N58_UNSUPPORTED_YEAR_PRESET'; end if;
      if tg_op='UPDATE' and old.calendar_preset_id is not null and
        (new.calendar_preset_id is null or new.deleted_at is not null or
          (new.hijri_start,new.hijri_end) is distinct from (old.hijri_start,old.hijri_end)) then
        raise exception using errcode='22023',message='N58_SELECTED_YEAR_IDENTITY_BLOCKED'; end if;
      if new.calendar_preset_id is not null and new.deleted_at is not null then
        raise exception using errcode='22023',message='N58_SELECTED_YEAR_RETIREMENT_BLOCKED'; end if;
      if new.calendar_preset_id is not null and not v_fresh_restore and
        (select count(*) from rakeezx.terms t where t.owner_id=new.owner_id and t.year_id=new.id
          and t."index" in (1,2) and t.deleted_at is null)<>2 then
        raise exception using errcode='22023',message='N58_EXISTING_TERMS_REQUIRED'; end if;
      if tg_op='UPDATE' and exists(select 1 from rakeezx.calendars c where c.owner_id=new.owner_id
        and c.year_id=new.id and c.preset_id is not null and
        not rakeezx.n58_valid_preset(c.preset_id,new.hijri_start,new.hijri_end)) then
        raise exception using errcode='22023',message='N58_SCOPED_YEAR_IDENTITY_BLOCKED'; end if;
    end if;
  elsif tg_table_name='calendars' then
    if tg_op='UPDATE' and (new.year_id,new.source,new.preset_id) is distinct from (old.year_id,old.source,old.preset_id) then
      raise exception using errcode='22023',message='N58_IMMUTABLE_CALENDAR_SCOPE'; end if;
    if tg_op='DELETE' then
      if old.preset_id is not null or v_year.calendar_preset_id is not null then
        raise exception using errcode='22023',message='N58_CALENDAR_HARD_DELETE_BLOCKED'; end if;
    else
      if new.preset_id is not null and (new.source<>'custom' or v_year.deleted_at is not null or
        not rakeezx.n58_valid_preset(new.preset_id,v_year.hijri_start,v_year.hijri_end)) then
        raise exception using errcode='22023',message='N58_INVALID_CUSTOM_SCOPE'; end if;
      if not v_fresh_restore then
        perform rakeezx.n58_validate_overrides(new.owner_id,new.year_id,new.preset_id,new.term_date_overrides);
      end if;
      if v_year.calendar_preset_id is not null and new.preset_id is null and not v_fresh_restore and
        (tg_op='INSERT' or (v_row-array['updated_at','client_updated_at','device_id','revision','field_revisions']) is distinct from
          (v_old-array['updated_at','client_updated_at','device_id','revision','field_revisions'])) then
        raise exception using errcode='22023',message='N58_LEGACY_CALENDAR_WRITE_BLOCKED'; end if;
    end if;
  elsif tg_table_name='calendar_days' then
    if tg_op='UPDATE' and (new.calendar_id,new.date) is distinct from (old.calendar_id,old.date) then
      raise exception using errcode='22023',message='N58_IMMUTABLE_DAY_IDENTITY'; end if;
    if v_year.calendar_preset_id is not null and not v_fresh_restore then
      if tg_op='DELETE' or v_calendar.preset_id is null or v_calendar.deleted_at is not null then
        if tg_op='UPDATE' and v_row-array['updated_at','client_updated_at','device_id','revision','field_revisions'] =
          v_old-array['updated_at','client_updated_at','device_id','revision','field_revisions'] then return new; end if;
        raise exception using errcode='22023',message='N58_UNSCOPED_DAY_WRITE_BLOCKED'; end if;
    end if;
  elsif tg_table_name='terms' then
    if tg_op='UPDATE' and (new.year_id,new."index") is distinct from (old.year_id,old."index") then
      raise exception using errcode='22023',message='N58_IMMUTABLE_TERM_IDENTITY'; end if;
    if v_year.calendar_preset_id is not null then
      if not v_fresh_restore and (tg_op='DELETE' or (tg_op='UPDATE' and new.deleted_at is not null)) then
        raise exception using errcode='22023',message='N58_TERM_RETIREMENT_BLOCKED'; end if;
      if not v_fresh_restore and ((tg_op='INSERT' and (new.start_date is not null or new.end_date is not null or new.calendar_id is not null)) or
        (tg_op='UPDATE' and (new.start_date,new.end_date,new.calendar_id) is distinct from (old.start_date,old.end_date,old.calendar_id))) then
        raise exception using errcode='22023',message='N58_USE_SCOPED_TERM_OVERRIDES'; end if;
    end if;
    -- An override cannot be orphaned even in a prepared, not-yet-selected scope.
    if tg_op='DELETE' or (tg_op='UPDATE' and new.deleted_at is not null) then
      if exists(select 1 from rakeezx.calendars c where c.owner_id=(v_row->>'owner_id')::uuid
        and c.year_id=v_year_id and c.deleted_at is null and c.term_date_overrides ? (v_row->>'id')) then
        raise exception using errcode='22023',message='N58_OVERRIDE_TERM_RETIREMENT_BLOCKED'; end if;
    end if;
  elsif tg_table_name in ('teachings','sections') then
    if tg_op='UPDATE' and (v_year.calendar_preset_id is not null or
      (tg_table_name='sections' and exists(select 1 from rakeezx.years y where y.owner_id=new.owner_id
        and y.id=v_old->>'year_id' and y.calendar_preset_id is not null)) or
      (tg_table_name='teachings' and exists(select 1 from rakeezx.terms t join rakeezx.years y
        on y.owner_id=t.owner_id and y.id=t.year_id where t.owner_id=new.owner_id
        and t.id=v_old->>'term_id' and y.calendar_preset_id is not null))) and ((tg_table_name='teachings' and
      (v_row->>'section_id',v_row->>'subject_id',v_row->>'term_id') is distinct from
      (v_old->>'section_id',v_old->>'subject_id',v_old->>'term_id')) or
      (tg_table_name='sections' and v_row->>'year_id' is distinct from v_old->>'year_id')) then
      -- Retain the stable parent identity used by recorded contexts/history.
      raise exception using errcode='22023',message='N58_IMMUTABLE_TEACHING_PARENT'; end if;
    if tg_table_name='teachings' and v_year.calendar_preset_id is not null and tg_op<>'DELETE' and
      not exists(select 1 from rakeezx.sections s where s.owner_id=(v_row->>'owner_id')::uuid and s.id=v_row->>'section_id' and s.year_id=v_year_id) then
      raise exception using errcode='22023',message='N58_TEACHING_YEAR_MISMATCH'; end if;
  elsif tg_table_name='sessions' and tg_op<>'DELETE' then
    if tg_op='UPDATE' then
      if new.calendar_context is distinct from old.calendar_context then
        raise exception using errcode='22023',message='N58_IMMUTABLE_SESSION_CONTEXT'; end if;
      if (old.calendar_context is not null or v_year.calendar_preset_id is not null or
        exists(select 1 from rakeezx.teachings x join rakeezx.terms t on t.owner_id=x.owner_id and t.id=x.term_id
          join rakeezx.years y on y.owner_id=t.owner_id and y.id=t.year_id
          where x.owner_id=old.owner_id and x.id=old.teaching_id and y.calendar_preset_id is not null)) and
        (new.teaching_id,new.date,new.period) is distinct from (old.teaching_id,old.date,old.period) then
        raise exception using errcode='22023',message='N58_IMMUTABLE_SESSION_IDENTITY'; end if;
    else
      v_context:=new.calendar_context;
      if v_context is null and v_year.calendar_preset_id is not null and not v_fresh_restore then
        raise exception using errcode='22023',message='N58_SESSION_CONTEXT_REQUIRED'; end if;
      if v_context is not null then
        if pg_catalog.jsonb_typeof(v_context)<>'object' or pg_catalog.octet_length(v_context::text)>2048 or
          not (v_context ?& array['yearId','termId','presetId','selectionRevision','kind','source']) or
          v_context-array['yearId','termId','presetId','selectionRevision','kind','source','label']<>'{}'::jsonb or
          pg_catalog.jsonb_typeof(v_context->'yearId')<>'string' or pg_catalog.jsonb_typeof(v_context->'termId')<>'string' or
          pg_catalog.jsonb_typeof(v_context->'presetId')<>'string' or pg_catalog.jsonb_typeof(v_context->'kind')<>'string' or
          pg_catalog.jsonb_typeof(v_context->'source')<>'string' or
          (v_context ? 'label' and (pg_catalog.jsonb_typeof(v_context->'label')<>'string' or pg_catalog.length(v_context->>'label')>500)) or
          pg_catalog.jsonb_typeof(v_context->'selectionRevision')<>'number' or
          (v_context->>'selectionRevision') !~ '^[1-9][0-9]{0,17}$' or
          v_context->>'yearId' is distinct from v_year_id or v_context->>'termId' is distinct from v_term.id or
          not rakeezx.n58_valid_preset(v_context->>'presetId',v_year.hijri_start,v_year.hijri_end) or
          v_context->>'kind' not in ('study','holiday','national','founding','exam','event','remote','suspension') or
          v_context->>'source' not in ('custom','official','default') or v_term.deleted_at is not null or v_year.deleted_at is not null or
          not exists(select 1 from rakeezx.teachings x where x.owner_id=new.owner_id and x.id=new.teaching_id and x.deleted_at is null) then
          raise exception using errcode='22023',message='N58_INVALID_SESSION_CONTEXT'; end if;
        if not v_fresh_restore and (v_year.calendar_preset_id is null or
          v_context->>'presetId' is distinct from v_year.calendar_preset_id or
          (v_context->>'selectionRevision')::bigint is distinct from (v_year.field_revisions->>'calendar_selection')::bigint) then
          raise exception using errcode='40001',message='N58_STALE_CALENDAR_SELECTION'; end if;
      end if;
    end if;
  end if;
  if tg_op='DELETE' then return old; else return new; end if;
end; $function$

CREATE OR REPLACE FUNCTION rakeezx.provision_account_workspace(p_defaults jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_owner uuid := auth.uid(); v_profile rakeezx.profile%rowtype;
  v_year jsonb; v_calendar jsonb; v_subject jsonb; v_row jsonb;
  v_hash text; v_manifest jsonb;
begin
  if v_owner is null then raise exception using errcode='42501', message='Authentication required'; end if;
  select * into v_profile from rakeezx.profile where owner_id=v_owner for update;
  if v_profile.owner_id is null or v_profile.provisioning_state not in ('PROVISIONING','READY') or
      v_profile.profile_status <> 'READY' then
    raise exception using errcode='42501', message='Account provisioning has not begun';
  end if;
  if v_profile.provisioning_state='READY' and
      rakeezx.account_provisioning_foundation_complete(v_owner) then
    return pg_catalog.jsonb_build_object('contract',rakeezx.account_contract(),
      'snapshot',rakeezx.account_provisioning_snapshot());
  end if;
  if not exists(select 1 from rakeezx.account_access_grants where owner_id=v_owner and
      grant_type='beta_full' and status='active' and (expires_at is null or expires_at > now())) then
    raise exception using errcode='42501', message='Beta access is required';
  end if;
  if p_defaults is null or pg_catalog.jsonb_typeof(p_defaults) <> 'object' or
      pg_catalog.jsonb_array_length(p_defaults->'years') <> 1 or
      pg_catalog.jsonb_array_length(p_defaults->'terms') <> 2 or
      pg_catalog.jsonb_array_length(p_defaults->'subjects') <> 1 or
      pg_catalog.jsonb_array_length(p_defaults->'calendars') <> 1 or
      pg_catalog.jsonb_array_length(p_defaults->'timeProfiles') <> 4 or
      pg_catalog.jsonb_array_length(p_defaults->'calendarDays') < 1 then
    raise exception using errcode='22023', message='Invalid foundation shape';
  end if;
  if v_profile.provisioning_state='READY' and
      v_profile.provisioning_hash is distinct from pg_catalog.md5(p_defaults::text) then
    raise exception using errcode='42501', message='Provisioning repair snapshot mismatch';
  end if;
  v_year := p_defaults->'years'->0;
  v_calendar := p_defaults->'calendars'->0;
  v_subject := p_defaults->'subjects'->0;
  if v_year->>'id' <> 'y:1448-1449' or (v_year->>'hijriStart')::int <> 1448 or
      (v_year->>'hijriEnd')::int <> 1449 or v_year->>'status' <> 'active' or
      v_calendar->>'id' <> 'cal:y:1448-1449:preset:sa-western-1448-1449' or
      v_calendar->>'yearId' <> 'y:1448-1449' or
      v_calendar->>'source' <> 'preset:sa-western-1448-1449' or
      v_subject->>'id' <> 'sub:digital-skills' or v_subject->>'slug' <> 'digital-skills' or
      v_subject->>'name' <> 'المهارات الرقمية' then
    raise exception using errcode='22023', message='Invalid foundation identity';
  end if;
  -- A crash may leave a matching subset from an older interrupted flow. Only
  -- missing IDs can be inserted; conflicting or unrelated existing rows stop.
  if v_profile.provisioning_state<>'READY' and (
    exists(select 1 from rakeezx.years r where r.owner_id=v_owner and
      (r.id<>v_year->>'id' or r.deleted_at is not null or r.label is distinct from v_year->>'label' or
       r.hijri_start is distinct from (v_year->>'hijriStart')::int or
       r.hijri_end is distinct from (v_year->>'hijriEnd')::int or
       r."order" is distinct from (v_year->>'order')::int or r.status is distinct from v_year->>'status')) or
    exists(select 1 from rakeezx.calendars r where r.owner_id=v_owner and
      (r.id<>v_calendar->>'id' or r.deleted_at is not null or
       r.year_id is distinct from v_calendar->>'yearId' or r.source is distinct from 'moe' or
       r.label is distinct from v_calendar->>'label')) or
    exists(select 1 from rakeezx.subjects r where r.owner_id=v_owner and
      (r.id<>v_subject->>'id' or r.deleted_at is not null or
       r.name is distinct from v_subject->>'name' or r.slug is distinct from v_subject->>'slug')) or
    exists(select 1 from rakeezx.terms r where r.owner_id=v_owner and
      r.id not in (select value->>'id' from pg_catalog.jsonb_array_elements(p_defaults->'terms'))) or
    exists(select 1 from rakeezx.calendar_days r where r.owner_id=v_owner and
      r.id not in (select value->>'id' from pg_catalog.jsonb_array_elements(p_defaults->'calendarDays'))) or
    exists(select 1 from rakeezx.time_profiles r where r.owner_id=v_owner and
      r.id not in (select value->>'id' from pg_catalog.jsonb_array_elements(p_defaults->'timeProfiles')))) then
    raise exception using errcode='23505', message='Conflicting foundation requires explicit recovery';
  end if;
  for v_row in select value from pg_catalog.jsonb_array_elements(p_defaults->'terms') loop
    if v_row->>'yearId' <> v_year->>'id' or v_row->>'id' <>
        'tm:y:1448-1449:' || (v_row->>'index') or (v_row->>'index')::int not in (1,2) then
      raise exception using errcode='22023', message='Invalid term identity';
    end if;
    if v_profile.provisioning_state<>'READY' and exists(select 1 from rakeezx.terms r where r.owner_id=v_owner and r.id=v_row->>'id' and
      (r.deleted_at is not null or r.year_id is distinct from v_row->>'yearId' or
       r.name is distinct from v_row->>'name' or r."index" is distinct from (v_row->>'index')::int or
       r.start_date is distinct from nullif(v_row->>'startDate','')::date or
       r.end_date is distinct from nullif(v_row->>'endDate','')::date or
       r.status is distinct from v_row->>'status' or r.calendar_id is distinct from v_row->>'calendarId')) then
      raise exception using errcode='23505', message='Conflicting term requires explicit recovery';
    end if;
  end loop;
  for v_row in select value from pg_catalog.jsonb_array_elements(p_defaults->'calendarDays') loop
    if v_row->>'calendarId' <> v_calendar->>'id' or v_row->>'id' <>
        'cd:' || (v_calendar->>'id') || ':' || (v_row->>'date') then
      raise exception using errcode='22023', message='Invalid calendar day identity';
    end if;
    if v_profile.provisioning_state<>'READY' and exists(select 1 from rakeezx.calendar_days r where r.owner_id=v_owner and r.id=v_row->>'id' and
      (r.deleted_at is not null or r.calendar_id is distinct from v_row->>'calendarId' or
       r.date is distinct from (v_row->>'date')::date or r.kind is distinct from v_row->>'kind' or
       r.label is distinct from v_row->>'label')) then
      raise exception using errcode='23505', message='Conflicting calendar day requires explicit recovery';
    end if;
  end loop;
  for v_row in select value from pg_catalog.jsonb_array_elements(p_defaults->'timeProfiles') loop
    if v_row->>'id' not in ('time-profile:default:summer','time-profile:default:winter',
        'time-profile:default:ramadan','time-profile:default:hybrid') or
        pg_catalog.jsonb_typeof(v_row->'periods') <> 'array' or
        pg_catalog.jsonb_typeof(v_row->'overrides') <> 'object' then
      raise exception using errcode='22023', message='Invalid timing profile';
    end if;
    if v_profile.provisioning_state<>'READY' and exists(select 1 from rakeezx.time_profiles r where r.owner_id=v_owner and r.id=v_row->>'id' and
      (r.deleted_at is not null or r.name is distinct from v_row->>'name' or
       r."order" is distinct from (v_row->>'order')::int or r.periods is distinct from v_row->'periods' or
       r.overrides is distinct from v_row->'overrides' or
       r.active_from is distinct from nullif(v_row->>'activeFrom','')::date or
       r.active_to is distinct from nullif(v_row->>'activeTo','')::date)) then
      raise exception using errcode='23505', message='Conflicting timing profile requires explicit recovery';
    end if;
  end loop;
  if (select count(distinct value->>'id') from pg_catalog.jsonb_array_elements(p_defaults->'terms')) <> 2 or
      (select count(distinct value->>'id') from pg_catalog.jsonb_array_elements(p_defaults->'calendarDays')) <>
        pg_catalog.jsonb_array_length(p_defaults->'calendarDays') or
      (select count(distinct value->>'id') from pg_catalog.jsonb_array_elements(p_defaults->'timeProfiles')) <> 4 then
    raise exception using errcode='22023', message='Duplicate foundation identity';
  end if;

  insert into rakeezx.years(owner_id,id,label,hijri_start,hijri_end,"order",status)
    values(v_owner,v_year->>'id',v_year->>'label',(v_year->>'hijriStart')::int,
      (v_year->>'hijriEnd')::int,(v_year->>'order')::int,v_year->>'status')
    on conflict (owner_id,id) do nothing;
  insert into rakeezx.calendars(owner_id,id,year_id,source,label)
    values(v_owner,v_calendar->>'id',v_calendar->>'yearId','moe',v_calendar->>'label')
    on conflict (owner_id,id) do nothing;
  for v_row in select value from pg_catalog.jsonb_array_elements(p_defaults->'terms') loop
    insert into rakeezx.terms(owner_id,id,year_id,name,"index",start_date,end_date,status,calendar_id)
      values(v_owner,v_row->>'id',v_row->>'yearId',v_row->>'name',(v_row->>'index')::int,
        nullif(v_row->>'startDate','')::date,nullif(v_row->>'endDate','')::date,
        v_row->>'status',v_row->>'calendarId') on conflict (owner_id,id) do nothing;
  end loop;
  insert into rakeezx.subjects(owner_id,id,name,slug)
    values(v_owner,v_subject->>'id',v_subject->>'name',v_subject->>'slug')
    on conflict (owner_id,id) do nothing;
  for v_row in select value from pg_catalog.jsonb_array_elements(p_defaults->'calendarDays') loop
    insert into rakeezx.calendar_days(owner_id,id,calendar_id,date,kind,label)
      values(v_owner,v_row->>'id',v_row->>'calendarId',(v_row->>'date')::date,
        v_row->>'kind',v_row->>'label') on conflict (owner_id,id) do nothing;
  end loop;
  for v_row in select value from pg_catalog.jsonb_array_elements(p_defaults->'timeProfiles') loop
    insert into rakeezx.time_profiles(owner_id,id,name,"order",periods,overrides,active_from,active_to)
      values(v_owner,v_row->>'id',v_row->>'name',(v_row->>'order')::int,
        v_row->'periods',v_row->'overrides',nullif(v_row->>'activeFrom','')::date,
        nullif(v_row->>'activeTo','')::date) on conflict (owner_id,id) do nothing;
  end loop;
  v_hash := pg_catalog.md5(p_defaults::text);
  v_manifest := pg_catalog.jsonb_build_object(
    'years',pg_catalog.jsonb_build_array(v_year->>'id'),
    'calendars',pg_catalog.jsonb_build_array(v_calendar->>'id'),
    'subjects',pg_catalog.jsonb_build_array(v_subject->>'id'),
    'terms',(select pg_catalog.jsonb_agg(value->>'id') from pg_catalog.jsonb_array_elements(p_defaults->'terms')),
    'calendarDays',(select pg_catalog.jsonb_agg(value->>'id') from pg_catalog.jsonb_array_elements(p_defaults->'calendarDays')),
    'timeProfiles',(select pg_catalog.jsonb_agg(value->>'id') from pg_catalog.jsonb_array_elements(p_defaults->'timeProfiles')));
  perform pg_catalog.set_config('rakeezx.account_provisioning_control','allow',true);
  update rakeezx.profile set provisioning_state='READY', provisioning_version=1,
      provisioning_hash=v_hash, provisioning_manifest=v_manifest,
      provisioning_completed_at=coalesce(provisioning_completed_at,now()) where owner_id=v_owner;
  if not rakeezx.account_provisioning_foundation_complete(v_owner) then
    raise exception using errcode='23514', message='Incomplete account foundation cannot be READY';
  end if;
  return pg_catalog.jsonb_build_object('contract',rakeezx.account_contract(),
    'snapshot',rakeezx.account_provisioning_snapshot());
end;
